"""Synthetic audio generated by code (silence, tones, noise) for tests and the --mock evaluation. No real recordings."""
from __future__ import annotations

import wave
from pathlib import Path

import numpy as np

SR = 16000


def silence(seconds: float, sr: int = SR) -> np.ndarray:
    return np.zeros(int(seconds * sr), dtype=np.float32)


def tone(freq: float = 440.0, seconds: float = 1.0, amplitude: float = 0.3, sr: int = SR) -> np.ndarray:
    t = np.arange(int(seconds * sr)) / sr
    return (amplitude * np.sin(2 * np.pi * freq * t)).astype(np.float32)


def noise(seconds: float = 1.0, amplitude: float = 0.05, sr: int = SR, seed: int = 0) -> np.ndarray:
    return (amplitude * np.random.default_rng(seed).standard_normal(int(seconds * sr))).astype(np.float32)


def write_wav(path: Path | str, samples: np.ndarray, sr: int = SR, width: int = 2, channels: int = 1) -> Path:
    """Write float samples (-1..1) as PCM. width: 1, 2, 3 or 4 bytes per sample. channels > 1 duplicates the signal."""
    path = Path(path)
    x = np.clip(np.asarray(samples, dtype=np.float64), -1.0, 1.0)
    if channels > 1:
        x = np.repeat(x[:, None], channels, axis=1).reshape(-1)
    if width == 1:
        raw = (x * 127 + 128).astype(np.uint8).tobytes()
    elif width == 2:
        raw = (x * 32767).astype("<i2").tobytes()
    elif width == 3:
        v = (x * (2**23 - 1)).astype(np.int32) & 0xFFFFFF
        raw = np.stack([v & 0xFF, (v >> 8) & 0xFF, (v >> 16) & 0xFF], axis=1).astype(np.uint8).tobytes()
    elif width == 4:
        raw = (x * (2**31 - 1)).astype("<i4").tobytes()
    else:
        raise ValueError("width must be 1, 2, 3 or 4")
    with wave.open(str(path), "wb") as w:
        w.setnchannels(channels)
        w.setsampwidth(width)
        w.setframerate(sr)
        w.writeframes(raw)
    return path


def write_mp3(path: Path | str, samples: np.ndarray, sr: int = SR) -> Path:
    """Encode an MP3 with PyAV (a test helper; raises if the encoder is not available)."""
    import av

    path = Path(path)
    out = av.open(str(path), "w")
    stream = out.add_stream("mp3", rate=sr)
    stream.layout = "mono"
    pcm = (np.clip(samples, -1, 1) * 32767).astype(np.int16).reshape(1, -1)
    frame = av.AudioFrame.from_ndarray(pcm, format="s16", layout="mono")
    frame.sample_rate = sr
    for packet in stream.encode(frame):
        out.mux(packet)
    for packet in stream.encode(None):
        out.mux(packet)
    out.close()
    return path
